-- Adivinhe pela Carreira do Vila Nova (career_players).
-- GERADO por `node tooling/vilanova_content/generate_seed_sql.mjs` a partir de
-- docs/vila_nova_data/arena/career_path.json — não edite à mão.
--
-- Rode no projeto Supabase do VILA NOVA — NUNCA no do Goiás nem no do
-- Bragantino (a trava abaixo para se não for). Idempotente.
--
-- 30 jogadores READY. `is_goias` é a chave LEGADA que o app lê como
-- "passagem pelo clube ativo" (aqui: pelo Vila Nova), vinda de `is_club` no pacote.

do $$
begin
  if not exists (select 1 from public.clubs where id = '3a6b1e27-8441-533d-b6b8-99fdcfdf1c3e' and slug = 'vilanova')
     or exists (select 1 from public.clubs where slug <> 'vilanova') then
    raise exception 'este nao e o projeto Supabase do Vila Nova -- PARE';
  end if;
end $$;

on conflict (id) do update set club_id = excluded.club_id, answer = excluded.answer, accepted_answers = excluded.accepted_answers, position = excluded.position, club_career = excluded.club_career, national_teams = excluded.national_teams, sort_order = excluded.sort_order, is_active = excluded.is_active;
